//! SpaceLens desktop application.
//!
//! ```text
//! SpaceLens.exe [--scan <PFAD>]
//! ```

// No console window in release builds; debug builds keep it for logs.
#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

mod app;
mod diag;
mod models;

use std::process::ExitCode;

use spacelens_settings as settings;
use spacelens_win::{elevation, shell};

/// Code generated by `slint-build` from `ui/`. Lints are relaxed only here;
/// the project's strict rules still apply to all hand-written code.
mod ui {
    #![allow(
        clippy::all,
        clippy::pedantic,
        clippy::unwrap_used,
        clippy::expect_used,
        clippy::undocumented_unsafe_blocks,
        clippy::todo,
        clippy::dbg_macro
    )]
    slint::include_modules!();
}

pub use ui::*;

fn main() -> ExitCode {
    diag::init(spacelens_win::known::data_dir().map(|d| d.join("logs")));
    install_panic_hook();

    let scan_arg = parse_scan_arg();
    let elevated = elevation::is_elevated();
    diag::log(&format!(
        "Start SpaceLens {} ({})",
        env!("CARGO_PKG_VERSION"),
        if elevated { "Administrator" } else { "Standardbenutzer" }
    ));
    if elevated {
        // Lets directory opens bypass ACLs (read-only) so protected folders
        // are measured too.
        elevation::enable_backup_privilege();
    }

    let ui = match MainWindow::new() {
        Ok(ui) => ui,
        Err(e) => {
            shell::message_box("SpaceLens", &format!("Das Fenster konnte nicht erstellt werden:\n{e}"), true);
            return ExitCode::FAILURE;
        }
    };
    let settings_path = spacelens_win::known::settings_dir().map(|d| d.join(settings::FILE));
    let (settings, note) = match &settings_path {
        Some(path) => settings::Settings::load(path),
        None => (settings::Settings::default(), settings::LoadNote::Missing),
    };
    let app = app::App::new(&ui, elevated, settings, settings_path);
    if note == settings::LoadNote::Corrupt {
        ui.set_status(
            "Einstellungen waren beschädigt und wurden zurückgesetzt (alte Datei: settings.json.corrupt).".into(),
        );
    }

    if let Some(path) = scan_arg {
        ui.set_scan_path(path.into());
        app.start_scan();
    }

    let result = ui.run();
    app.shutdown();
    match result {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            shell::message_box("SpaceLens", &format!("Unerwarteter Fehler der Oberfläche:\n{e}"), true);
            ExitCode::FAILURE
        }
    }
}

/// `--scan <PFAD>`: start scanning immediately (used after the UAC relaunch).
fn parse_scan_arg() -> Option<String> {
    let mut args = std::env::args_os().skip(1);
    while let Some(arg) = args.next() {
        if arg == "--scan" {
            return args.next().map(|p| p.to_string_lossy().into_owned());
        }
    }
    None
}

/// Every panic gets a crash report on disk. Fatal ones (not inside workers,
/// which catch panics per directory/file) are also shown to the user,
/// together with the report's location.
fn install_panic_hook() {
    let default = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| {
        let report = diag::crash_report(info);
        let thread = std::thread::current();
        let name = thread.name().unwrap_or("?");
        if name.starts_with("scan-worker") || name.starts_with("mft-parser") {
            default(info);
            return;
        }
        let where_ = report.map_or_else(
            || "Es konnte kein Bericht geschrieben werden.".to_string(),
            |p| format!("Ein Bericht wurde gespeichert:\n{}", p.display()),
        );
        shell::message_box(
            "SpaceLens – Unerwarteter Fehler",
            &format!("Ein interner Fehler ist aufgetreten (Thread \u{201E}{name}\u{201C}):\n\n{info}\n\n{where_}"),
            true,
        );
    }));
}
